    <fieldset class="kind-filters" aria-label="Filter by kind">
      <legend>Kind</legend>
      <button type="button" data-kind="all" class="chip active">All 55</button>
      <button type="button" data-kind="story" class="chip">Story</button>
      <button type="button" data-kind="missable" class="chip">Missable</button>
      <button type="button" data-kind="collectibles" class="chip">Collectibles</button>
      <button type="button" data-kind="activities" class="chip">Activities</button>
      <button type="button" data-kind="online" class="chip">Online</button>
    </fieldset>
    <label class="grade-filter">Grade
      <select id="grade">
        <option value="all">All grades</option>
        <option value="platinum">Platinum</option>
        <option value="gold">Gold</option>
        <option value="silver">Silver</option>
        <option value="bronze">Bronze</option>
      </select>
    </label>
    <label class="grade-filter">Show
      <select id="show">
        <option value="all">All trophies</option>
        <option value="todo">Not earned yet</option>
        <option value="earned">Earned</option>
      </select>
    </label>
    <label class="toggle"><input id="spoilers" type="checkbox"> Hide story spoilers</label>
  </div>
  <div class="controls tools">
    <button id="export" type="button">Export progress (.json)</button>
    <label class="import-btn">Import progress <input id="import" type="file" accept="application/json,.json"></label>
    <button id="reset" type="button">Reset progress</button>
    <p class="save-note" id="save-note">Progress saves automatically in this browser.</p>
  </div>
  <p class="result-count" id="result-count"></p>
  <ul class="trophy-list" id="trophy-list"></ul>
