/* Leonida Trophy Guide — own design. Dark theme, sunset accent, system fonts only. */
:root {
  --bg: #14101d;
  --panel: #1e1829;
  --panel-2: #262033;
  --ink: #f2ecff;
  --muted: #b9b0cf;
  --line: #3a324e;
  --accent: #ff7a59;
  --accent-2: #2dd4bf;
  --gold: #f5c542;
  --silver: #c9d2dc;
  --bronze: #d08a4e;
  --platinum: #7fe3f0;
  --danger: #ff5d73;
  --radius: 12px;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--ink);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  line-height: 1.5;
}
.masthead {
  display: flex;
  flex-wrap: wrap;
  gap: 24px;
  justify-content: space-between;
  align-items: flex-start;
  padding: 28px 24px 20px;
  background: linear-gradient(135deg, #2b1740 0%, #14101d 55%, #0f2a2e 100%);
  border-bottom: 3px solid var(--accent);
}
.eyebrow {
  margin: 0 0 6px;
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--accent-2);
}
h1 { margin: 0 0 8px; font-size: 2rem; line-height: 1.1; }
.tagline { margin: 0; max-width: 560px; color: var(--muted); }
.progress-card {
  background: var(--panel);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 14px 18px;
  min-width: 280px;
}
.progress-count { margin: 0 0 8px; font-size: 1.1rem; }
